import { API } from '../../../common/constants';
export async function checkAgentsExist(http, agentConfigName, dataSourceId) {
  const response = await http.get(API.AGENT_API.CONFIG_EXISTS, {
    query: {
      agentConfigName,
      dataSourceId
    }
  });
  return response;
}